import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷二·22","description":"易小帖 - 卷二·22","frontmatter":{"title":"卷二·22","description":"易小帖 - 卷二·22"},"headers":[],"relativePath":"classics/yixiaotie/062.md","filePath":"classics/yixiaotie/062.md"}'),o={name:"classics/yixiaotie/062.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷二·22",tabindex:"-1"},[r("卷二·22 "),e("a",{class:"header-anchor",href:"#卷二·22","aria-label":"Permalink to “卷二·22”"},"​")],-1),e("p",null,"《左傳》「三墳五典八索九丘」，不知所指。孔安國謂：三墳者伏羲神農黃帝之書，五典者少昊顓頊高辛唐虞之書。則其三與五，亦但合三皇五帝數目。而作偽三墳者，竊子華子，出於一，立於兩，成於三。連山以之而呈形，歸藏以之而御氣，大易以之而立數，遂造三墳名色，曰：山墳、形墳、氣墳。謂即羲易，與連山龜藏三皇之易，則無理矣。至八索九丘，孔氏謂夏商周所傳大訓，然又謂八卦之設謂之八索。求真義也。九州之制謂之九丘，言九州所聚也。則豈八卦之設，在夏商後耶。若《山堂考索》曰：八索八卦之說。則正述孔氏語。然孔氏又謂：先君孔子讚易道以黜八索，述職方以除九丘。則八索九丘，總為夫子所除黜者，更不可解。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
